From 7973813b2b699cc8a3a54916523343b5250bf1cc Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:01:04 +0100
Subject: [PATCH] xdgactivation: end the task manager startup once its token is
 used

When the window's app id differs from the launched desktop file, the
task manager can't match it to the startup and shows both until the
window is mapped. End that startup once the window uses its token.

BUG: 453776
---
 src/xdgactivationv1.cpp | 12 +++++++++---
 1 file changed, 9 insertions(+), 3 deletions(-)

diff --git a/src/xdgactivationv1.cpp b/src/xdgactivationv1.cpp
index ce6cce956f..c28858ba82 100644
--- a/src/xdgactivationv1.cpp
+++ b/src/xdgactivationv1.cpp
@@ -52,7 +52,7 @@ XdgActivationV1Integration::XdgActivationV1Integration(XdgActivationV1Interface
     });

     connect(Workspace::self(), &Workspace::windowActivated, this, [this](Window *window) {
-        if (!m_activation || !window || m_lastTokenAppId != window->desktopFileName()) {
+        if (m_lastToken.isEmpty() || !window || m_lastTokenAppId != window->desktopFileName()) {
             return;
         }
         clearFeedback();
@@ -122,6 +122,11 @@ void XdgActivationV1Integration::activateSurface(SurfaceInterface *surface, cons

     if (!window->readyForPainting()) {
         window->setActivationToken(token);
+        // The task manager already lists the window, and can't match it to the
+        // startup when the app id differs from the one the token was made for
+        if (token == m_lastToken) {
+            m_activation.reset();
+        }
         return;
     }

@@ -136,10 +141,11 @@ void XdgActivationV1Integration::activateSurface(SurfaceInterface *surface, cons

 void XdgActivationV1Integration::clearFeedback()
 {
-    if (m_activation) {
+    if (!m_lastToken.isEmpty()) {
         Q_EMIT effects->startupRemoved(m_lastToken);
-        m_activation.reset();
+        m_lastToken.clear();
     }
+    m_activation.reset();
 }

 }
